// Generated by OrchestKit Claude Plugin
// Created: 2026-08-10

/**
 * Model the persistent Bash shell's working directory (#3411).
 *
 * WHY THIS EXISTS. Claude Code runs Bash tool calls in a shell whose cwd
 * persists across calls, but it does not tell hooks what that cwd is:
 *
 *   • Hook processes are spawned with cwd = the PROJECT dir, not the shell's.
 *     Measured 2026-08-10 from real invocations. `git-validator` logged
 *     "Blocked on protected branch: main" at 16:14-16:21 while the shell was
 *     in `.worktrees/wtscan` on a feature branch.
 *   • `CwdChanged` does NOT fire for a `cd` inside a Bash call. The event is
 *     real and its payload keys (`old_cwd`/`new_cwd`) are correct, but across
 *     1763 recorded sessions not one state file ever gained a `shell_cwd`, and
 *     `hooks.log` contains exactly one `cwd-changed` line, and it was a synthetic probe.
 *   • No hook payload carries it either: `createBaseHookInput` fills `cwd`
 *     from a session-level getter.
 *
 * So the only place this information exists is the command strings themselves,
 * which ork already sees. This module turns a command into its effect on the
 * shell's cwd; `posttool/bash/session-heartbeat-publisher` persists the result
 * and `pretool/bash/git-validator` reads it back.
 *
 * The segment/quoting model deliberately MIRRORS `locateGitSegment` rather than
 * reusing it: that function answers "where is the git token", returns null when
 * no git appears, and a `cd`-only command is precisely the case tracked here.
 *
 * Failure modes lean the safe way. `unknown` clears the record so the guard
 * falls back to its fail-closed verdict instead of trusting a stale directory,
 * and anything quoted or sub-shelled reports `unchanged`, because a `cd` inside
 * `sh -c '...'` or `( ... )` genuinely does not move the parent shell.
 */

import { isAbsolute, join } from 'node:path';

/** What a command does to the persistent shell's cwd. */
export type CwdEffect =
  /** No top-level `cd`, so the shell stays where it was. */
  | { kind: 'unchanged' }
  /** Top-level `cd`s, in order. Relative targets compound. */
  | { kind: 'set'; targets: string[] }
  /** A cwd change we cannot model (`cd` with no target, `cd -`, pushd/popd). */
  | { kind: 'unknown' };

/**
 * Which `cd`s in this command will still be in effect for the NEXT command?
 *
 * Only top-level, unquoted, single-target `cd`s count. The scan stops at the
 * first quote, backtick, `$` or `|`, and treats a leading `(` as a subshell,
 * in every one of those cases the parent shell's cwd is unaffected, so
 * whatever was accumulated so far is the honest answer.
 */
export function extractPersistentCd(command: string): CwdEffect {
  const targets: string[] = [];
  let pos = 0;
  const n = command.length;

  const done = (): CwdEffect =>
    targets.length > 0 ? { kind: 'set', targets } : { kind: 'unchanged' };

  while (pos < n) {
    while (pos < n && /\s/.test(command[pos])) pos++;
    if (pos >= n) break;

    // A subshell or brace group: its `cd` is scoped to the child, and we
    // cannot reliably find where it ends. Keep what we have and stop.
    if (command[pos] === '(' || command[pos] === '{') return done();

    let end = pos;
    let sawQuote = false;
    while (end < n) {
      const ch = command[end];
      if (ch === '"' || ch === "'" || ch === '`' || ch === '$') {
        sawQuote = true;
        break;
      }
      if (ch === ';' || (ch === '&' && command[end + 1] === '&') || ch === '|') {
        break;
      }
      end++;
    }

    const segment = command.slice(pos, end).trim();

    // `cd <one-token>` is the only form we model. `cd` alone goes to $HOME and
    // `cd -` to the previous directory; both are modelable in principle but
    // pushd/popd are not, and guessing wrong here silently mis-routes a
    // security verdict. Report unknown and let the reader fail closed.
    if (/^(cd|pushd|popd)$/.test(segment) || /^cd\s+-\s*$/.test(segment)) {
      return { kind: 'unknown' };
    }
    if (/^(pushd|popd)\s/.test(segment)) {
      return { kind: 'unknown' };
    }

    const cdMatch = segment.match(/^cd\s+([^\s]+)$/);
    if (cdMatch) {
      const target = cdMatch[1];
      // `cd --` / `cd -L` style flags: not a directory we can resolve.
      if (target.startsWith('-')) return { kind: 'unknown' };
      targets.push(target);
    }

    // A quote appeared: the rest is untrusted, and a quoted `cd` does not move
    // the parent shell. Stop with what we have.
    if (sawQuote) return done();

    if (end >= n) break;
    if (command[end] === ';') pos = end + 1;
    else if (command[end] === '&') pos = end + 2;
    else return done(); // '|', stop
  }

  return done();
}

/**
 * Apply an effect to the currently-known shell cwd.
 *
 * Relative targets compound against the running value, which is why `cd a &&
 * cd b` lands in `<base>/a/b` and not `<base>/b`. Returns null for `unknown`,
 * which callers must persist as "no record" rather than leaving the old value
 * in place.
 */
export function applyCwdEffect(
  current: string | null,
  effect: CwdEffect,
  projectDir: string,
): string | null {
  if (effect.kind === 'unknown') return null;
  if (effect.kind === 'unchanged') return current;

  let dir = current || projectDir;
  for (const target of effect.targets) {
    dir = isAbsolute(target) ? target : join(dir, target);
  }
  return dir;
}
